"use strict";(globalThis.webpackChunkgrc||=[]).push([[84846],{78117(a){a.exports=JSON.parse('{"citeKey":"sun1995applicationaccuracy","slug":"sun-1995-application-accuracy-7067","title":"Application and Accuracy of the Parallel Diagonal Dominant Algorithm","authors":["X.-H. Sun"],"venue":"Parallel Computing","type":"Journal","entryType":"article","date":"August, 1995","year":1995,"era":"archive","month":8,"doi":"10.1016/0167-8191(95)00018-j","abstract":"The Parallel Diagonal Dominant (PDD) algorithm is an efficient tridiagonal solver. In this paper, a detailed study of the PDD algorithm is given. First the PDD algorithm is extended to solve periodic tridiagonal systems and its scalability is studied. Then the reduced PDD algorithm, which has a smaller operation count than that of the conventional sequential algorithm for many applications, is proposed. Accuracy analysis is provided for a class of tridiagonal systems, the symmetric and skew-symmetric Toeplitz tridiagonal systems. Implementation results show that the analysis gives a good bound on the relative error, and the PDD and reduced PDD algorithms are good candidates for emerging massively parallel machines.","hasAbstract":true,"lede":"A detailed study of the PDD algorithm is given.","links":{"pdf":"https://grc.iit.edu/papers/1995/sun-1995-application-accuracy-7067.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);